package org.eclipse.kura.web.session;

import java.io.IOException;
import java.util.Optional;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;

import org.eclipse.kura.web.Console;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class CreateSessionSecurityHandler implements SecurityHandler {

    private static final Logger logger = LoggerFactory.getLogger(CreateSessionSecurityHandler.class);

    @Override
    public boolean handleSecurity(HttpServletRequest request, HttpServletResponse response) throws IOException {

        final Optional<HttpSession> session = Console.instance().getOrCreateSessionBounded(request);

        if (!session.isPresent()) {
            logger.warn("rejecting request to {}, the maximum number of unauthenticated sessions has been reached",
                    request.getRequestURI());
            response.sendError(HttpServletResponse.SC_SERVICE_UNAVAILABLE);
            return false;
        }

        return true;
    }

}
